window.__posterData({"id": "lisa-eriksson", "name": "Lisa Eriksson", "folder": "Lisa-Eriksson_Ai-raveposter_HT26", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "//Kommentarer i koden är skillnader som blev i steg 1, men som inte gjorde slutresultatet annorlunda. Ai har endast strukturerat om koden och skrivit den på ett annorlunda sätt, men min poster ser likadan ut som innan jag bad den refaktorisera den.\n\n//Använder konstanter för canvasens storlek, hastihet på cirklarna, slumpade färger, cirklarnas storlek samt knapparnas storlek. Jag har använt mig av \"let\" istället. Ai använder let på resterande variabler. Här används inte variabeln W som jag har i min kod.\n \n// ---------- Konstanter ----------\nconst CANVAS_WIDTH = 600;\nconst CANVAS_HEIGHT = 724;\nconst FRAME_RATE = 5;\n \nconst COLORS = ['#4deeea', '#74ee15', '#ffe700', '#f000ff', '#001eff', '#FD009B', '#ffaa00'];\n \nconst RANDOM_CIRCLE_SIZE = 20;\nconst MAX_CIRCLES = 30; // max antal slumpcirklar som syns samtidigt\nconst BUTTON_SIZE = { w: 60, h: 20 };\n \n// NYTT: gnistor som följer musen\nconst MAX_SPARKLES = 12; // max antal gnistor i spåret\nconst SPARKLE_SIZE = 16; // storleken på den nyaste gnistan\n \n// ---------- Tillstånd ----------\nlet img;\n \n// Den rörliga cirkelns position, storlek och hastighet\nlet x = 0;\nlet y = 0;\nconst circleSize = 100;\nlet speedX = 100;\nlet speedY = 100;\n \n// Sparar x, y och färg för varje slumpcirkel\nlet randomCircles = [];\n \n// NYTT: sparar x, y och färg för varje gnista i musspåret\nlet sparkles = [];\n \n// ---------- Setup ----------\nasync function setup() {\n  // bilden laddas\n  img = await loadImage('rave-1.jpg');\n \n  createCanvas(CANVAS_WIDTH, CANVAS_HEIGHT);\n  background(50);\n  image(img, 0, 0);\n \n  //Knapparna för start och stopp har den skrivit på ett kortare sätt där den endast anger positionerna i x och y-led, eftersom resterande information gällande storlek finns som en konstant tidigare i koden. \n  createControlButton('START', 250, 600, loop);\n  createControlButton('STOP', 320, 600, noLoop);\n \n  // Justerar hur fort animationen ska gå\n  frameRate(FRAME_RATE);\n}\n \n// Skapar en knapp med given text, position och klickfunktion\nfunction createControlButton(label, posX, posY, onPress) {\n  const button = createButton(label);\n \n  //Pos är inte något jag hört från tidhgare föreläsningar. Förstår det som att det är en förkortning av position i x och y-led. Här har Ai även skrivit knapparnas storlek som W och H, vilket jag inte gjort. Storlekarna för W och H skrivs istället högre upp i koden där konstanten för knapparna beskrivs. \n  button.position(posX, posY);\n  button.size(BUTTON_SIZE.w, BUTTON_SIZE.h);\n  button.mousePressed(onPress);\n  return button;\n}\n \n// ---------- Draw ----------\nfunction draw() {\n  // Rensa canvasen och rita bakgrunden på nytt varje frame\n  background(50);\n  image(img, 0, 0);\n \n  // Slumpar en färg som används för texten och den rörliga cirkeln\n  fill(random(COLORS));\n \n  drawTexts();\n \n  strokeWeight(1);\n \n  //Använder annan kod jämfört med mig, något mer kortfattad.\n  // Den rörliga cirkeln ritas bara när musknappen är nedtryckt\n  if (mouseIsPressed) {\n    drawBouncingCircle();\n  }\n \n  updateRandomCircles();\n  drawRandomCircles();\n \n  // NYTT: gnistspåret uppdateras och ritas överst\n  updateSparkles();\n  drawSparkles();\n}\n \n//Texten har skrivits på olika sätt, där Ai har skrivit dessa koder inom samma klammer. Detta gör att man behöver ange typsnitt högst upp, för att det sedan ska gälla genom hela koden inom klmmern. \n// Texter med typsnitt och storlek\nfunction drawTexts() {\n  stroke(0);\n  textFont('Helvetica');\n \n  textSize(75);\n  strokeWeight(20);\n  text('RAVEFESTIVAL', 25, 200);\n \n  textSize(20);\n  strokeWeight(10);\n  text('Lisa Eriksson', 240, 240);\n}\n \n//För att få cirklarna att flytta sig över canvasen har vi använt liknande kod. Däremot har jag använt variabeln W, vilket jag tror inte var nödvändigt då Ai inte använt det, men ändå fungerar koden lika. \n\n// Ritar cirkeln, flyttar den diagonalt och byter riktning vid kanterna\nfunction drawBouncingCircle() {\n  circle(x + circleSize / 2, y + circleSize / 2, circleSize);\n \n  x += speedX;\n  y += speedY;\n \n  if (x <= 0 || x >= width - circleSize) {\n    speedX *= -1; // byter riktning vid vänster eller höger kant\n  }\n  if (y <= 0 || y >= height - circleSize) {\n    speedY *= -1; // byter riktning vid över- eller underkant\n  }\n}\n \n//Steg 2: detta har jag bett Ai att ändra och lägga till så att antalet cirklar inte blir fler och fler ju längre koden går. Prompten jag skrev till Ai: detta är min nuvarande kod. gör de slumpmässiga cirklarna till ett maxantal som får synas på canvasen, som sedan loopar tills stoppknappen klickas på.\n\n// Lägger till en ny cirkel och tar bort den äldsta när maxantalet nåtts\nfunction updateRandomCircles() {\n  randomCircles.push({\n    x: random(0, CANVAS_WIDTH),\n    y: random(0, CANVAS_HEIGHT),\n    color: random(COLORS),\n  });\n \n  if (randomCircles.length > MAX_CIRCLES) {\n    randomCircles.shift(); // tar bort den äldsta cirkeln\n  }\n}\n \n// Ritar alla sparade cirklar, var och en med sin egen färg\nfunction drawRandomCircles() {\n  strokeWeight(1);\n  stroke(0);\n  for (const c of randomCircles) {\n    fill(c.color);\n    circle(c.x, c.y, RANDOM_CIRCLE_SIZE);\n  }\n}\n//Steg 1: min orginalkod var 103 rader och den refaktoriserade efter steg 1 är 95 rader. Den har alltså blivit kortare då Ai kortat ner text och button koderna.\n \n// NYTT: Lägger till en gnista på musens position (bara när musen är över canvasen) och tar bort den äldsta när maxantalet nåtts\nfunction updateSparkles() {\n  const insideCanvas = mouseX >= 0 && mouseX <= width && mouseY >= 0 && mouseY <= height;\n \n  if (insideCanvas) {\n    sparkles.push({\n      x: mouseX,\n      y: mouseY,\n      color: random(COLORS),\n    });\n  }\n \n  // Om musen ligger still eller lämnar canvasen försvinner spåret gradvis\n  if (sparkles.length > MAX_SPARKLES || (!insideCanvas && sparkles.length > 0)) {\n    sparkles.shift(); // tar bort den äldsta gnistan\n  }\n}\n \n// NYTT: Ritar gnistorna som fyruddiga stjärnor, ju äldre desto mindre\nfunction drawSparkles() {\n  strokeWeight(1);\n  stroke(0);\n  for (let i = 0; i < sparkles.length; i++) {\n    const s = sparkles[i];\n    const size = SPARKLE_SIZE * ((i + 1) / sparkles.length);\n    fill(s.color);\n    drawStar(s.x, s.y, size);\n  }\n}\n \n// NYTT: Ritar en fyruddig stjärna med mittpunkt i (cx, cy) och radie r\nfunction drawStar(cx, cy, r) {\n  beginShape();\n  for (let i = 0; i < 8; i++) {\n    // varannan punkt ligger långt ut (spets), varannan nära mitten\n    const radius = i % 2 === 0 ? r : r / 3;\n    const angle = (TWO_PI / 8) * i - HALF_PI;\n    vertex(cx + cos(angle) * radius, cy + sin(angle) * radius);\n  }\n  endShape(CLOSE);\n}\n\n//Steg 3: den nya koden som Ai lagt till är stjärnspår som följer muspekaren, som sedan minskas och tillslut försvinner desto äldre de blir. Jag tycker den förändringen tillförde något i designen som följde rave-teamt. Stjärnorna passade in med de valda färgerna, samt att en stjärna förstärker känslan av dans/disco till musik. Även att de följer muspekarens rörelse gör postern mer interaktiv. Jag hade dock önskat att få en lite roligare implementering, något i form av rörelse i texten eller kanske stjärnor som poppar upp som konfetti. Har svårt att förstå koden som Ai gjort för dessa stjärnor, när den skrivit siffror och variabler multiplicerat och adderat med varandra. Detta har jag svårt att förstå då jag inte riktigt begriper hur man vet vad som ska multipliceras med vad eller liknande. Under lektioner har vi använt detta för att få en cirkel att byta riktining i kanterna, vilket jag använt i min kod. Men skulle krävas en tydligare förklaring på vad som används och varför. \n\n", "assets": {"rave-1.jpg": {"mime": "image/webp", "b64": ""}, "rave.jpg": {"mime": "image/webp", "b64": ""}}});
